(5291388, 768473, 22301, '<td valign="top">My guess is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=49954" rel="nofollow" target="_blank">Hawkeyelonewolf</a>. Just a guess though, I feel the image is too cramped, it is an interesting bird lamp.</td>', 'My guess is  Hawkeyelonewolf. Just a guess though, I feel the image is too cramped, it is an interesting bird lamp.', '2009-03-05 15:28:00.000000', NULL, 1),
(5291389, 768962, 22301, '<td valign="top">I guess this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=61552" rel="nofollow" target="_blank">Zeuss</a>? I know he at least is in this line of work. I think the image is a little dark, but that was probably intentional.</td>', 'I guess this is  Zeuss? I know he at least is in this line of work. I think the image is a little dark, but that was probably intentional.', '2009-03-05 15:28:07.000000', NULL, 1),
(5291391, 769866, 22301, '<td valign="top">I like the color palette.</td>', 'I like the color palette.', '2009-03-05 15:28:24.000000', NULL, 1),
(5291392, 769693, 22301, '<td valign="top">I can only think this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=13390" rel="nofollow" target="_blank">goinskiing</a>, it looks like that wonderful Utah powder. I think you may get dinged for including yourself in the image though.</td>', 'I can only think this is  goinskiing, it looks like that wonderful Utah powder. I think you may get dinged for including yourself in the image though.', '2009-03-05 15:28:35.000000', NULL, 1),
(5291394, 769461, 22301, '<td valign="top">I like this, but wish that it was shot from further back and with a longer focal length so that it felt a little more compressed so that everything seem closer to me. I don''t feel I can get in and examine the details.</td>', 'I like this, but wish that it was shot from further back and with a longer focal length so that it felt a little more compressed so that everything seem closer to me. I don''t feel I can get in and examine the details.', '2009-03-05 15:29:02.000000', NULL, 1),
(5291395, 770089, 22301, '<td valign="top">for me the yellow is overbearing to the design left from the chaos, but I suppose chaos in itself is overbearing.</td>', 'for me the yellow is overbearing to the design left from the chaos, but I suppose chaos in itself is overbearing.', '2009-03-05 15:29:14.000000', NULL, 1),
(5291396, 770045, 22301, '<td valign="top">The texture of the food I find excellent, the blinding handle of the fork I find overbearing. I would have tried a tighter crop to get rid of this.</td>', 'The texture of the food I find excellent, the blinding handle of the fork I find overbearing. I would have tried a tighter crop to get rid of this.', '2009-03-05 15:29:23.000000', NULL, 1),
(5291397, 769823, 22301, '<td valign="top">I guess this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=89723" rel="nofollow" target="_blank">sempermarine</a>''s entry.<br/>I think a few highlights especially on the Bear are too hot. Also it seems a bit oversharpened as there are jagged edges in some of the finer details and more noticeable along the red line down the coat. A very good idea though as I am sure these two things define who you are. 6</td>', 'I guess this is  sempermarine''s entry.I think a few highlights especially on the Bear are too hot. Also it seems a bit oversharpened as there are jagged edges in some of the finer details and more noticeable along the red line down the coat. A very good idea though as I am sure these two things define who you are. 6', '2009-03-05 15:29:27.000000', NULL, 1),
(5291403, 770114, 22301, '<td valign="top">My guess is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=98408" rel="nofollow" target="_blank">okky</a>, she is the only one who is listed as living in wodonga and she also has a few horse photos. <br/>I think the composition feelsa little cramped because many of the objects are cut off. It does show your interest very well though.</td>', 'My guess is  okky, she is the only one who is listed as living in wodonga and she also has a few horse photos. I think the composition feelsa little cramped because many of the objects are cut off. It does show your interest very well though.', '2009-03-05 15:33:42.000000', NULL, 1),
