INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5291893, 770099, 59029, '<td valign="top">I''d guess a fine artist or illustrator...and as the drawing depicts a baby''s feet, and a wedding ring on left hand, I might hazard a guess at a woman.  And even if I''m wrong, still a lovely drawing and effective use of penceil to draw us in. 7</td>', 'I''d guess a fine artist or illustrator...and as the drawing depicts a baby''s feet, and a wedding ring on left hand, I might hazard a guess at a woman.  And even if I''m wrong, still a lovely drawing and effective use of penceil to draw us in. 7', '2009-03-05 20:28:19.000000', NULL, 1),
