(5295917, 769927, 92403, '<td valign="top">it''s cool that the bulb actually is working.<br/>really like the blue background.</td>', 'it''s cool that the bulb actually is working.really like the blue background.', '2009-03-08 14:41:00.000000', NULL, 1),
(5295922, 769346, 92403, '<td valign="top">Very cool... and definitely with a good sense of humor!</td>', 'Very cool... and definitely with a good sense of humor!', '2009-03-08 14:44:17.000000', NULL, 1),
