(5296394, 769508, 23317, '<td valign="top">The result is a bit flat.  Probably needed better lighting, background, and pov.  Good idea to catch the smoke.</td>', 'The result is a bit flat.  Probably needed better lighting, background, and pov.  Good idea to catch the smoke.', '2009-03-08 20:48:47.000000', NULL, 1),
(5296396, 769814, 23317, '<td valign="top">The lack of focus with the "Butterflies Feeding!!!" sign and red &amp; white flower distracted me.  Nice contrast witht he green and yellow though.</td>', 'The lack of focus with the "Butterflies Feeding!!!" sign and red & white flower distracted me.  Nice contrast witht he green and yellow though.', '2009-03-08 20:50:48.000000', NULL, 1),
